//! 🛡️ Borrowed role admission scoped to the new PDF/VT raw-frontier operation.
use semio_framework_value::{DslValue as V, ValueError as E, ValueRefusalKind as K};
#[derive(Clone, Copy)]
enum Role { Graph, Object, Identity, Entry, Cos, Filter, Predictor, Ccitt }
fn refusal() -> E { E::new(K::InvalidValue, "RestoreDpartGraph payload differs from its owned roles") }
fn row<'a>(value: &'a V, allowed: &[&str], required: &[&str]) -> Result<&'a [(String, V)], E> {
    let V::Object(fields) = value else { return Err(refusal()); };
    if fields.len() > allowed.len() || fields.iter().any(|(key, _)| !allowed.contains(&key.as_str()) || fields.iter().filter(|(name, _)| name == key).count() != 1) || required.iter().any(|key| !fields.iter().any(|(name, _)| name == key)) { return Err(refusal()); }
    Ok(fields)
}
fn get<'a>(fields: &'a [(String, V)], key: &str) -> Result<&'a V, E> { fields.iter().find(|(name, _)| name == key).map(|(_, value)| value).ok_or_else(refusal) }
fn optional<'a>(fields: &'a [(String, V)], key: &str) -> Option<&'a V> { fields.iter().find(|(name, _)| name == key).map(|(_, value)| value).filter(|value| !matches!(value, V::Null)) }
fn array(value: &V) -> Result<&[V], E> { if let V::Array(values) = value { Ok(values) } else { Err(refusal()) } }
fn text(value: &V) -> Result<&str, E> { if let V::String(value) = value { Ok(value) } else { Err(refusal()) } }
fn boolean(value: &V) -> Result<(), E> { if matches!(value, V::Bool(_)) { Ok(()) } else { Err(refusal()) } }
fn unsigned(value: &V, maximum: u64) -> Result<(), E> { if let V::Number(number) = value { if number.as_u64().is_some_and(|value| value <= maximum) { return Ok(()); } } Err(refusal()) }
fn signed(value: &V, minimum: i64, maximum: i64) -> Result<(), E> { if let V::Number(number) = value { if number.as_i64().is_some_and(|value| value >= minimum && value <= maximum) { return Ok(()); } } Err(refusal()) }
fn octets(value: &V) -> Result<(), E> { if matches!(value, V::Bytes(_)) { return Ok(()); } for value in array(value)? { unsigned(value, 255)?; } Ok(()) }
/// 🛡️ Checks only the new operation envelope and complete ordered COS frontier before owned decode.
pub(crate) fn validate_payload(value: &V, tagged: bool) -> Result<(), E> {
    let fields = if tagged { row(value, &["mutation", "graph"], &["mutation", "graph"])? } else { row(value, &["graph"], &["graph"])? };
    if tagged && text(get(fields, "mutation")?)? != "restoreDpartGraph" { return Err(refusal()); }
    let mut pending = vec![(get(fields, "graph")?, Role::Graph)];
    while let Some((value, role)) = pending.pop() {
        match role {
            Role::Graph => { let fields = row(value, &["objects", "catalogExtra"], &["objects", "catalogExtra"])?; for value in array(get(fields, "objects")?)? { pending.push((value, Role::Object)); } for value in array(get(fields, "catalogExtra")?)? { pending.push((value, Role::Entry)); } }
            Role::Object => { let fields = row(value, &["id", "value"], &["id", "value"])?; pending.push((get(fields, "id")?, Role::Identity)); pending.push((get(fields, "value")?, Role::Cos)); }
            Role::Identity => { let fields = row(value, &["num", "gen"], &["num", "gen"])?; unsigned(get(fields, "num")?, u32::MAX as u64)?; unsigned(get(fields, "gen")?, u16::MAX as u64)?; }
            Role::Entry => { let fields = row(value, &["key", "value"], &["key", "value"])?; text(get(fields, "key")?)?; pending.push((get(fields, "value")?, Role::Cos)); }
            Role::Cos => {
                let kind = text(get(row(value, &["kind", "value", "negative", "coefficient", "scale", "num", "gen", "dict", "data", "filters"], &["kind"])?, "kind")?)?;
                let keys: &[&str] = match kind { "null" => &["kind"], "real" => &["kind", "negative", "coefficient", "scale"], "ref" => &["kind", "num", "gen"], "stream" => &["kind", "dict", "data", "filters"], "bool" | "int" | "str" | "name" | "array" | "dict" => &["kind", "value"], _ => return Err(refusal()) };
                let fields = row(value, keys, keys)?;
                match kind {
                    "null" => {}, "bool" => boolean(get(fields, "value")?)?, "int" => signed(get(fields, "value")?, i64::MIN, i64::MAX)?, "str" => octets(get(fields, "value")?)?, "name" => { text(get(fields, "value")?)?; },
                    "real" => { boolean(get(fields, "negative")?)?; text(get(fields, "coefficient")?)?; unsigned(get(fields, "scale")?, u32::MAX as u64)?; },
                    "ref" => { unsigned(get(fields, "num")?, u32::MAX as u64)?; unsigned(get(fields, "gen")?, u16::MAX as u64)?; },
                    "array" => { for value in array(get(fields, "value")?)? { pending.push((value, Role::Cos)); } },
                    "dict" => { for value in array(get(fields, "value")?)? { pending.push((value, Role::Entry)); } },
                    "stream" => { for value in array(get(fields, "dict")?)? { pending.push((value, Role::Entry)); } octets(get(fields, "data")?)?; for value in array(get(fields, "filters")?)? { pending.push((value, Role::Filter)); } },
                    _ => return Err(refusal()),
                }
            }
            Role::Filter => {
                let kind = text(get(row(value, &["kind", "predictor", "earlyChange", "colorTransform", "parameters", "globals", "name"], &["kind"])?, "kind")?)?;
                let (allowed, required): (&[&str], &[&str]) = match kind { "flate" => (&["kind", "predictor"], &["kind"]), "lzw" => (&["kind", "predictor", "earlyChange"], &["kind", "earlyChange"]), "dct" => (&["kind", "colorTransform"], &["kind"]), "ccitt" => (&["kind", "parameters"], &["kind", "parameters"]), "jbig2" => (&["kind", "globals"], &["kind"]), "crypt" => (&["kind", "name"], &["kind"]), "asciiHex" | "ascii85" | "runLength" | "jpx" => (&["kind"], &["kind"]), _ => return Err(refusal()) };
                let fields = row(value, allowed, required)?;
                if let Some(value) = optional(fields, "predictor") { pending.push((value, Role::Predictor)); }
                if kind == "lzw" { boolean(get(fields, "earlyChange")?)?; }
                if let Some(value) = optional(fields, "colorTransform") { unsigned(value, u32::MAX as u64)?; }
                if kind == "ccitt" { pending.push((get(fields, "parameters")?, Role::Ccitt)); }
                if let Some(value) = optional(fields, "globals") { octets(value)?; }
                if let Some(value) = optional(fields, "name") { text(value)?; }
            }
            Role::Predictor => { let keys = &["predictor", "colors", "bitsPerComponent", "columns"]; let fields = row(value, keys, keys)?; for (_, value) in fields { unsigned(value, u32::MAX as u64)?; } }
            Role::Ccitt => { let fields = row(value, &["k", "columns", "rows", "blackIs1", "encodedByteAlign", "endOfLine", "endOfBlock", "damagedRowsBeforeError"], &[])?; for (key, value) in fields { match key.as_str() { "k" => signed(value, i32::MIN as i64, i32::MAX as i64)?, "blackIs1" | "encodedByteAlign" | "endOfLine" | "endOfBlock" => boolean(value)?, _ => unsigned(value, u32::MAX as u64)? } } }
        }
    }
    Ok(())
}

